      "Pain in thoracic spine",
      "Other chronic pain",
      "Lower abdominal pain, unspecified",
      "Abdominal distension (gaseous)",
      "Type 2 diabetes mellitus with diabetic chronic kidney disease",
      "Type 2 diabetes mellitus with diabetic peripheral angiopathy without gangrene",
      "Hypertensive chronic kidney disease with stage 1 through stage 4 chronic kidney disease, or unspecified chronic kidney disease",
      "Unspecified atherosclerosis of native arteries of extremities, unspecified extremity",
      "Chronic kidney disease, unspecified",
      "Kidney transplant status",
      "Other viral infections of unspecified site",
      "Other specified diseases of pancreas",
      "Long term (current) use of insulin",
      "Obstructive sleep apnea (adult) (pediatric)",
      "Atherosclerotic heart disease of native coronary artery without angina pectoris",
      "Hyperlipidemia, unspecified"
    ]
  }
}
